int majorityElement(vector<int>& nums) {
    int candidate = 0, count = 0;
    for (int x : nums) {
        if (count == 0) candidate = x;            // the prefix so far has cancelled out; start fresh
        count += (x == candidate) ? 1 : -1;
    }
    return candidate;
}

public int majorityElement(int[] nums) {
    int candidate = 0, count = 0;
    for (int x : nums) {
        if (count == 0) candidate = x;            // the prefix so far has cancelled out; start fresh
        count += (x == candidate) ? 1 : -1;
    }
    return candidate;
}
